def parse_vc(res):
    """Extract variance components from a fitted MixedLM (vcomp + cov_re + scale)."""
    names = list(res.model.exog_vc.names)
    d = {f"{n} Var": float(v) for n, v in zip(names, np.asarray(res.vcomp, dtype=float))}
    d["Group Var"] = float(np.asarray(res.cov_re).ravel()[0])
    d["Scale"] = float(res.scale)
    return d


def manual_aic(res, n_fixed=None):
    """Manual AIC/BIC for REML-free comparison: MLE-style with variance params counted.
    statsmodels returns NaN for REML; we refit ML for AIC comparisons instead."""
    k = res.params.size
    return float(2 * k - 2 * res.llf)


