def elimination_agreement(score, with_prior):
    """Mean A: fraction of eliminated celebrity-weeks correctly assignable to the
    top-2 of the predicted ranking, ex-ante (hazard only) vs with the fan-appeal
    prior g_iw = hazard * exp(gamma * u_i)."""
    base = score.copy()
    base["score"] = base["hazard_prob"]
    if with_prior:
        base["score"] = base["hazard_prob"] * np.exp(gamma_hat * base["u_i"].fillna(0))
    ranks = base.groupby("week_num")["score"].rank(ascending=False)
    return float((ranks <= 2.0)[base["elim_now_obs"] > 0].mean())

